import std.io
import std.string

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let c = string.runeCode('A')
    io.println("A ${c}")
    let z = string.runeCode('中')
    io.println("zh ${z}")
    let r = string.runeFrom(66)
    io.println("r ${r}")
    return Ok(())
}
